function OverseaManagePersonnelFoodPopupCell:RefreshFoodShow(data)
    local isUnLock =  GameUtils.IsUnlockedSingle(data.unlockType, data.unlockNum, data.unlockId)
    KTool.SetActive(self.Lock.gameObject,not isUnLock)
    local goodNode = self.GoodNode
    if not isNull(goodNode) then
        local env = CfUtils.GetLuaScr(goodNode,GoodNodeMBPath)
        if env then
            env:Reload({goodsId = data.food})
            env:SetClickButtonAction(function(goodsId, id)
                ----点击出tip
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end
end

function OverseaManagePersonnelFoodPopupCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManagePersonnelFoodPopupCell